<section class="page-head"><div><p class="eyebrow">OYUN KATEGORİSİ</p><h1><?= e($category['name']) ?></h1><?php if(!empty($category['description'])): ?><p><?= e($category['description']) ?></p><?php endif; ?></div></section><section><div class="products"><?php foreach($products as $p): ?><article class="product"><a class="product-link" href="<?= e(url('product/'.rawurlencode($p['slug']))) ?>"><div class="product-image"><?php if($p['image']): ?><img src="<?= e($p['image']) ?>" alt="<?= e($p['name']) ?>"><?php else: ?><span>GAME</span><?php endif; ?></div><h3><?= e($p['name']) ?></h3><p><?= e($p['short_description']) ?></p><strong><?= number_format((float)$p['price'],2,',','.') ?> ₺</strong></a></article><?php endforeach; ?><?php if(!$products): ?><div class="empty">Bu kategoride henüz yayında ürün bulunmuyor.</div><?php endif; ?></div></section>